// t0 — entry stamp; resolves the speed TIER (superfast default) + preserves .query so every source reads it.
const j = $input.first().json;
const q = (j && j.query) || {};
var tier = String(q.tier || '').toLowerCase();
if (tier !== 'superfast' && tier !== 'fast' && tier !== 'normal') {
  tier = (q.full === '1' || q.tier === 'full') ? 'normal' : (q.fast === '1' ? 'fast' : 'superfast'); // back-compat + default superfast
}
const run = { transcripts: tier !== 'superfast', parallel: tier === 'normal', udyam: true, gweb: true, idfy_async: true };

  // #2 result-cache read — a fresh (<24h) hit for THIS buyer pull short-circuits the whole pipeline (cache-gate → respond-cached)
  var glid = String(q.glid || q.GLID || j.glid || '').trim();
  var __cached_result = null;
  try {
    if (String(q.nocache || '') !== '1' && glid && !q.mode) {
      var sd = $getWorkflowStaticData('global');
      var hit = sd.__extcache && sd.__extcache['res:' + glid + ':' + tier];
      if (hit && hit.payload && (Date.now() - (hit.ts || 0) < 86400000)) __cached_result = hit.payload;
    }
  } catch (e) {}
  var __job_id = glid + '_' + Date.now().toString(36);
  var __callback_url = String(q.callback_url || q.callbackUrl || '').trim() || null;
  return [{ json: Object.assign({}, j, { __cached_result: __cached_result, __t0: Date.now(), tier: tier, run: run, query: Object.assign({}, q, { tier: tier }), __job_id: __job_id, __callback_url: __callback_url }) }];

// INLINE-safe cap (~1 min): NEVER throw (would kill the sync pull) — flag timeout to route to calls-empty.
if ($runIndex > 6) return [{ json: { __timeout: true } }];
return $input.all();

// rows → most-recent N calls {url,date}; emit one item per call, or a single {__none} sentinel
const raw = $input.first().json;
const txt = String((raw && raw.data != null) ? raw.data : JSON.stringify(raw)).replace(/[\u0000-\u001f]/g, ' ');
let rows = [];
try { rows = (JSON.parse(txt).query_result && JSON.parse(txt).query_result.data.rows) || []; } catch (e) { rows = []; }
const calls = rows.map(r => ({ url: r.call_recording_url, date: r.eto_lead_ai_bot_response_insert_date || r.date })).filter(c => c.url);
return calls.length ? calls.map(c => ({ json: c })) : [{ json: { __none: true } }];

const __all = (n) => { try { return $(n).all().map(i => i.json || {}); } catch (e) { return []; } };
// [CEO] Joins each transcribed call back to its metadata. v44: rows WITHOUT audio never reached the
// transcription model (skipped upstream) — they are re-slotted here as honest 'no_audio', so counts stay
// truthful and no extraction is ever fabricated from silence. Alignment: the k-th real LLM output maps to
// the k-th audio-bearing source row (same order both sides), replacing the old fragile 1:1 positional join.
const src = __all('calls-parse').filter(j => j && j.url);
const b64All = __all('calls-audio-b64');
const withAudio = []; b64All.forEach((b, i) => { if (b.has_audio) withAudio.push(i); });
const real = $input.all().filter(it => !(it.json && it.json.__skipped_no_audio));
const byIdx = {}; real.forEach((it, k) => { if (k < withAudio.length) byIdx[withAudio[k]] = it; });
const perCall = src.map((meta, i) => {
  const b = b64All[i] || {};
  if (!b.has_audio) return { date: meta.date, url: meta.url, extraction: null, status: 'no_audio' };
  const it = byIdx[i] || {}; const j = it.json || {}; let ex = {};
  try { const c = j.choices && j.choices[0] && j.choices[0].message && j.choices[0].message.content; ex = typeof c === 'string' ? JSON.parse(c) : (c && typeof c === 'object' ? c : {}); } catch (e) {}
  const err = it.error || j.error || null;
  const hasData = !!(ex && ((Array.isArray(ex.products) && ex.products.length > 0) || ex.metadata || ex.lead_tag));
  return { date: meta.date, url: meta.url, extraction: hasData ? ex : null, status: hasData ? 'extracted' : (err ? 'error' : 'no_data') };
});
const ok = perCall.filter(c => c.status === 'extracted');
const noAudio = perCall.filter(c => c.status === 'no_audio').length;
return [{ json: { summary: { redash_records: src.length, call_count: ok.length, failed_count: src.length - ok.length, no_audio_count: noAudio, brief: src.length ? (ok.length + ' of ' + src.length + ' call(s) extracted (Go-schema)' + (noAudio ? ' · ' + noAudio + ' had no recording media (skipped, not failed)' : '')) : 'no call records from Redash', calls: ok, statuses: perCall.map(c => ({ url: c.url, date: c.date, status: c.status })) }, raw: { rows: src } } }];

// n8n does NOT expose binary base64 via $binary.data.data in HTTP-node expressions — read it here.
const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  let b64 = '';
  const bin = (items[i].binary && items[i].binary.data) || {};
  try { const buf = await this.helpers.getBinaryDataBuffer(i, 'data'); b64 = buf.toString('base64'); } catch (e) {}
  if (!b64 && typeof bin.data === 'string' && bin.data.length > 100 && /^[A-Za-z0-9+/=]+$/.test(bin.data.slice(0,120))) b64 = bin.data;
  const fmt = String(bin.mimeType || '').toLowerCase().includes('wav') ? 'wav' : 'mp3';
  out.push({ json: { audio_b64: b64, audio_format: fmt, has_audio: !!b64, bytes: b64 ? Math.round(b64.length * 0.75) : 0 } });
}
return out;
// v44 no_audio_skip: rows without audio are flagged so the LLM step is bypassed for them (assemble marks them no_audio).

// INLINE-safe cap (~1 min): NEVER throw (would kill the sync pull) — flag timeout to route to calls-empty.
if ($runIndex > 6) return [{ json: { __timeout: true } }];
return $input.all();

// PNS rows → per call {uc_id, offer_id, modref, mcat, subcat, circle, seller_id, date}. uc_id gates (SQL already filters valid calls). __none sentinel if empty.
const raw = $input.first().json;
const txt = String((raw && raw.data != null) ? raw.data : JSON.stringify(raw)).replace(/[\u0000-\u001f]/g, ' ');
let rows = [];
try { rows = (JSON.parse(txt).query_result && JSON.parse(txt).query_result.data.rows) || []; } catch (e) { rows = []; }
const clean = v => (v == null ? '' : String(v).replace(/\.0$/, ''));
const calls = rows.map(r => ({ uc_id: clean(r.pns_call_vendor_uniqueid), offer_id: clean(r.fk_eto_ofr_display_id), modref: r.pns_call_modrefname || '', mcat: r.pns_call_ref_prime_mcat || '', subcat: r.pns_call_ref_prime_subcat || '', circle: r.pns_call_caller_circle || '', seller_id: clean(r.pns_call_receiver_glusr_id), date: r.pns_call_record_date || '' })).filter(c => c.uc_id);
return calls.length ? calls.map(c => ({ json: c })) : [{ json: { __none: true } }];

// n8n does NOT expose binary base64 via $binary.data.data in HTTP-node expressions — read it here.
// v14.1: carry attribution (uc_id/offer_id) + b64_len + fetched MIME for ground-truth instrumentation;
// guard the fallback so a filesystem-mode store reference (binaryMode:"separate") can never leak as audio.
const items = $input.all();
const parse = $('pns-parse').all().map(x => x.json).filter(j => j && j.uc_id);
const out = [];
for (let i = 0; i < items.length; i++) {
  let b64 = '';
  const bin = (items[i].binary && items[i].binary.data) || {};
  try { const buf = await this.helpers.getBinaryDataBuffer(i, 'data'); b64 = buf.toString('base64'); } catch (e) {}
  // only accept an inline fallback that is plausibly real base64 (memory mode); reject store refs like "filesystem-v2".
  if (!b64 && typeof bin.data === 'string' && bin.data.length > 100 && /^[A-Za-z0-9+/=\r\n]+$/.test(bin.data)) b64 = bin.data;
  const mime = String(bin.mimeType || '').toLowerCase();
  const fmt = mime.includes('wav') ? 'wav' : 'mp3';
  const meta = parse[i] || {};
  out.push({ json: {
    audio_b64: b64,
    audio_format: fmt,
    has_audio: !!b64,
    b64_len: b64.length,
    bytes: b64 ? Math.round(b64.length * 0.75) : 0,
    mime: mime || null,
    uc_id: meta.uc_id, offer_id: meta.offer_id
  } });
}
return out;
// v44 no_audio_skip: rows without audio are flagged so the LLM step is bypassed for them (assemble marks them no_audio).

const __all = (n) => { try { return $(n).all().map(i => i.json || {}); } catch (e) { return []; } };
// [CEO] Joins each transcribed PNS call back to its metadata (uc_id, offer_id, date). v44: rows WITHOUT
// audio never reached the transcription model (skipped upstream) — re-slotted here as honest 'no_audio' with
// their byte counts, so the health line reads "skipped: no recording" instead of a fake 400 failure, and no
// extraction is ever fabricated from silence. Alignment: k-th real LLM output -> k-th audio-bearing row.
const src = __all('pns-parse').filter(j => j && j.uc_id);
const b64All = __all('pns-audio-b64');
const withAudio = []; b64All.forEach((b, i) => { if (b.has_audio) withAudio.push(i); });
const real = $input.all().filter(it => !(it.json && it.json.__skipped_no_audio));
const byIdx = {}; real.forEach((it, k) => { if (k < withAudio.length) byIdx[withAudio[k]] = it; });
const perCall = src.map((meta, i) => {
  const b64Item = b64All[i] || {};
  const base = { date: meta.date, uc_id: meta.uc_id, offer_id: meta.offer_id, product: meta.modref, mcat: meta.mcat, subcat: meta.subcat, circle: meta.circle, seller_id: meta.seller_id, audio_bytes: b64Item.bytes != null ? b64Item.bytes : null, b64_len: b64Item.b64_len != null ? b64Item.b64_len : null, mime: b64Item.mime || null };
  if (!b64Item.has_audio) return Object.assign(base, { extraction: null, status: 'no_audio', http_status: null, error_msg: null });
  const it = byIdx[i] || {}; const j = it.json || {}; let ex = {};
  try { const c = j.choices && j.choices[0] && j.choices[0].message && j.choices[0].message.content; ex = typeof c === 'string' ? JSON.parse(c) : (c && typeof c === 'object' ? c : {}); } catch (e) {}
  const err = it.error || j.error || null;
  const http_status = err ? (err.httpCode || err.statusCode || (err.context && err.context.httpCode) || 'error') : 200;
  const error_msg = err ? String((err.context && (err.context.data || err.context.body)) || err.description || err.message || JSON.stringify(err)).slice(0, 800) : null;
  const hasData = !!(ex && ((Array.isArray(ex.products) && ex.products.length > 0) || ex.metadata || ex.lead_tag));
  return Object.assign(base, { extraction: hasData ? ex : null, status: hasData ? 'extracted' : ((http_status && http_status !== 200) ? 'http_error' : 'no_data'), http_status: http_status, error_msg: error_msg });
});
const okCount = perCall.filter(c => c.status === 'extracted').length;
const noAudio = perCall.filter(c => c.status === 'no_audio').length;
return [{ json: { summary: { redash_records: src.length, call_count: okCount, failed_count: src.length - okCount, no_audio_count: noAudio, brief: src.length ? (okCount + ' of ' + src.length + ' PNS call(s) extracted (Go-schema)' + (noAudio ? ' · ' + noAudio + ' had no recording media (skipped, not failed)' : '')) : 'no PNS calls', calls: perCall, statuses: perCall.map(c => ({ uc_id: c.uc_id, date: c.date, product: c.product, offer_id: c.offer_id, status: c.status, bytes: c.audio_bytes, mime: c.mime, http: c.http_status, err: c.error_msg })) }, raw: { rows: src } } }];

// extract Data.signed_url from imutils (uc_id path → GCS). No S3 fallback for PNS.
return $input.all().map((it) => {
  let body = (it.json && it.json.data != null) ? it.json.data : it.json;
  if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) {} }
  let signed = '';
  if (body && typeof body === 'object') { signed = (body.Data && (body.Data.signed_url || body.Data.im_url)) || body.signed_url || body.signedUrl || body.url || ''; }
  else if (typeof body === 'string') { signed = String(body).trim(); }
  return { json: { signed_url: signed } };
});

// [CEO] Skip lane: these call rows had NO recording media (0 audio bytes). We mark them and pass them
// around the transcription model entirely — no LLM call, no 400 error, no invented transcript.
return $input.all().map(() => ({ json: { __skipped_no_audio: true } }));

// [CEO] Skip lane: these call rows had NO recording media (0 audio bytes). We mark them and pass them
// around the transcription model entirely — no LLM call, no 400 error, no invented transcript.
return $input.all().map(() => ({ json: { __skipped_no_audio: true } }));

// enrich-assemble — thin collector for buyer-intelligence-enrich.
// Reads terminal outputs of the PNS + Calls pipelines and packages
// { glid, fetched_at, sources: { pns_calls, calls }, __health }.
const ref = (n) => { try { const it = $(n).first(); return it ? it.json : null; } catch (e) { return null; } };
let glid = null; try { glid = $('t0').first().json.query.glid; } catch (e) {}
const sources = {
  pns_calls: ref('pns-assemble'),
  calls: ref('calls-assemble'),
};
const health = Object.keys(sources).map((k) => {
  const s = sources[k] || {};
  const h = s.__health || (s.summary && s.summary.__health) || {};
  return { node: h.node || k, ok: h.ok !== false, status: h.status || (h.ok === false ? 'error' : 'ok'), count: h.count != null ? h.count : null, error_msg: h.error_msg || h.reason || null, version: h.version || null };
});
return [{ json: { glid, fetched_at: new Date().toISOString(), sources, __health: health } }];
